        if not customers and "nodes" in instance:
            nodes = instance["nodes"]
            customers = [x for x in nodes if x != depot]
        if not customers and demands is not None and type(demands) is dict:
            customers = [k for k in demands.keys() if k != depot]

    def d(i, j):
        if dist is not None:
            return dist[i][j]
        if coords is not None:
            a = coords[i]
            b = coords[j]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            return (dx * dx + dy * dy) ** 0.5
        return 0.0

    def dem(c):
        if demands is None:
            return 0
        if type(demands) is dict:
            return demands.get(c, 0)
        return demands[c]

    if not customers:
        return []

    # Remove depot if present and make deterministic unique ordering.
    seen = {}
    cust = []
    for c in customers:
        if c == depot:
            continue
        if c not in seen:
            seen[c] = 1
            cust.append(c)

    # Deterministic seed ordering: far first, then high demand, then id.
    cust.sort(key=lambda x: (-d(depot, x), -dem(x), x))

    # Constructive phase: nearest/farthest hybrid greedy route growth.
    unrouted = cust[:]
    routes = []
    loads = []

    while unrouted:
        seed = None
        seed_idx = 0
        best_seed_key = None
        for i, c in enumerate(unrouted):
            dc = dem(c)
            if dc > capacity:
                dc = capacity + 1
            key = ( -d(depot, c), -dc, c)
            if best_seed_key is None or key < best_seed_key:
                best_seed_key = key
                seed = c
                seed_idx = i
        if seed is None:
            break

        route = [seed]
        load = dem(seed)
        unrouted.pop(seed_idx)

        while True:
            last = route[-1]
            best = None
            best_key = None
            for i, c in enumerate(unrouted):
                dc = dem(c)
                if load + dc > capacity:
                    continue
                inc = d(last, c) + d(c, depot) - d(last, depot)
                key = (inc, -dc, d(depot, c), c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (i, c, dc)
            if best is None:
                break
            i, c, dc = best
            route.append(c)
            load += dc
            unrouted.pop(i)

        routes.append(route)
        loads.append(load)

    # Repair phase: insert any leftover customers into best feasible place.
    leftovers = unrouted
    for c in leftovers:
        dc = dem(c)
        best_r = -1
        best_p = -1
        best_k = None
        for r in range(len(routes)):
            if loads[r] + dc > capacity:
                continue
            route = routes[r]
            prev = depot
            for p in range(len(route) + 1):
                nxt = depot if p == len(route) else route[p]
                cost = d(prev, c) + d(c, nxt) - d(prev, nxt)
                key = (cost, len(route), r, p, c)
                if best_k is None or key < best_k:
                    best_k = key
                    best_r = r
                    best_p = p
                if p < len(route):
                    prev = route[p]
        if best_r == -1:
            routes.append([c])
            loads.append(dc)
        else:
            routes[best_r].insert(best_p, c)
            loads[best_r] += dc

    # Local search helpers.
    def route_cost(route):
        if not route:
            return 0.0
        total = d(depot, route[0])
        for i in range(len(route) - 1):
            total += d(route[i], route[i + 1])
        total += d(route[-1], depot)
        return total

    # Intra-route 2-opt.
    changed = True
    while changed:
        changed = False
        for r in range(len(routes)):
            route = routes[r]
            n = len(route)
            if n < 4:
                continue
            improved = True
            while improved:
                improved = False
                base = route_cost(route)
                for i in range(n - 2):
                    a = depot if i == 0 else route[i - 1]
                    b = route[i]
                    for k in range(i + 2, n):
                        c = route[k - 1]
                        dnode = depot if k == n else route[k]
                        delta = (d(a, c) + d(b, dnode)) - (d(a, b) + d(c, dnode))
                        if delta < -1e-12:
                            route[i:k] = route[i:k][::-1]
                            improved = True
                            changed = True
                            break
                    if improved:
                        break
                if not improved:
                    break
            routes[r] = route

    # Inter-route relocate and swap improvements.
    improved = True
    while improved:
        improved = False

        # Relocate single customer.
        for r1 in range(len(routes)):
            if improved:
                break
            for i in range(len(routes[r1])):
                c = routes[r1][i]
                dc = dem(c)
                for r2 in range(len(routes)):
                    if r1 == r2 and len(routes[r1]) <= 1:
                        continue
                    if r1 != r2 and loads[r2] + dc > capacity:
                        continue

                    src = routes[r1]
                    dst = routes[r2]

                    prev1 = depot if i == 0 else src[i - 1]
                    next1 = depot if i == len(src) - 1 else src[i + 1]
                    remove_delta = d(prev1, next1) - d(prev1, c) - d(c, next1)

                    for p in range(len(dst) + 1):
                        prev2 = depot if p == 0 else dst[p - 1]
                        next2 = depot if p == len(dst) else dst[p]
                        add_delta = d(prev2, c) + d(c, next2) - d(prev2, next2)
                        delta = remove_delta + add_delta
                        if delta < -1e-12:
                            if r1 == r2:
                                if p == i or p == i + 1:
                                    continue
                                tmp = src.pop(i)
                                if p > i:
                                    p -= 1
                                dst.insert(p, tmp)
                            else:
                                tmp = src.pop(i)
                                loads[r1] -= dc
                                dst.insert(p, tmp)
                                loads[r2] += dc
                                if len(src) == 0:
                                    routes.pop(r1)
                                    loads.pop(r1)
                                improved = True
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

        if improved:
            continue

        # Swap between routes.
        for r1 in range(len(routes)):
            if improved:
                break
            for r2 in range(r1 + 1, len(routes)):
                for i in range(len(routes[r1])):
                    a = routes[r1][i]
                    da = dem(a)
                    for j in range(len(routes[r2])):
                        b = routes[r2][j]
                        db = dem(b)
                        if loads[r1] - da + db > capacity:
                            continue
                        if loads[r2] - db + da > capacity:
                            continue
                        s1 = routes[r1]
                        s2 = routes[r2]

                        a_prev = depot if i == 0 else s1[i - 1]
                        a_next = depot if i == len(s1) - 1 else s1[i + 1]
                        b_prev = depot if j == 0 else s2[j - 1]
                        b_next = depot if j == len(s2) - 1 else s2[j + 1]

                        old = d(a_prev, a) + d(a, a_next) + d(b_prev, b) + d(b, b_next)
                        new = d(a_prev, b) + d(b, a_next) + d(b_prev, a) + d(a, b_next)
                        if new + 1e-12 < old:
                            s1[i], s2[j] = s2[j], s1[i]
                            loads[r1] = loads[r1] - da + db
                            loads[r2] = loads[r2] - db + da
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

    return routes
